input.newString:
function pickChoice(side){
  if(S.cur>=QUESTIONS.length) return;
  // Guard: the transition to the next round is async (480ms). Without this lock a
  // fast second click (e.g. on the Skip button, which is never pointer-events:none)
  // scores the SAME question twice, inflating S.maxP and skipping a round.
  if(S.locked) return;
  S.locked=true;
  const q=QUESTIONS[S.cur];
  const ca=document.getElementById('card-a');
  const cb=document.getElementById('card-b');
  ca.style.pointerEvents='none'; cb.style.pointerEvents='none';
  const skipBtn=document.querySelector('.skip-btn');
  if(skipBtn){skipBtn.disabled=true;skipBtn.style.opacity='.5';skipBtn.style.pointerEvents='none';}

  if(side!=='skip'){
    const w=side==='a'?q.a.w:q.b.w;
    AXES.forEach(ax=>{S.scores[ax.key]+=(w[ax.key]||0);});
    const winner=side==='a'?ca:cb;
    const loser=side==='a'?cb:ca;
    winner.classList.add('winner');
    loser.classList.add('dimmed');
  }

  AXES.forEach(ax=>{
    const wa=Math.abs(q.a.w[ax.key]||0);
    const wb=Math.abs(q.b.w[ax.key]||0);
    S.maxP[ax.key]+=Math.max(wa,wb);
  });

  S.answers.push({q:q.id,choice:side});

  setTimeout(()=>{
    S.cur++;
    S.locked=false;
    updateSidebar();
    if(S.cur>=QUESTIONS.length) showLoading();
    else displayQ();
  },480);
}

