/* Budget chart */
const b=destData.budget;
const total=Object.values(b).reduce((s,v)=>s+v,0);
document.getElementById('r-total').textContent=fmt(total);
const BK=['flights','accommodation','food','activities','transport','shopping'];
const BL=['✈️ Flights','🏨 Hotels','🍽️ Food','🎯 Activities','🚌 Transport','🛍️ Shopping'];
const BC=['#FF6B6B','#FF9F43','#FFD93D','#10B981','#38BDF8','#8B5CF6'];
// Chart.js comes from a CDN. If it failed to load, fall back to the plain
// list instead of throwing and killing the rest of the results page.
const chartOK=(typeof Chart!=='undefined');
const chartWrap=document.getElementById('budget-chart-wrap');
if(chartOK){
  if(bChart){bChart.destroy();bChart=null;}
  const ctx=document.getElementById('budget-chart').getContext('2d');
  bChart=new Chart(ctx,{
    type:'doughnut',
    data:{
      labels:BL,
      datasets:[{data:BK.map(k=>b[k]),backgroundColor:BC,borderColor:'#FFFFFF',borderWidth:4,hoverOffset:12}]
    },
    options:{
      cutout:'68%',
      plugins:{
        legend:{display:false},
        tooltip:{callbacks:{label:c=>` ${c.label.replace(/✈️|🏨|🍽️|🎯|🚌|🛍️/g,'').trim()}: ${fmt(c.raw)}`}}
      },
      animation:{duration:1000,easing:'easeInOutQuart'}
    }
  });
}else if(chartWrap){
  chartWrap.style.display='none';
}
document.getElementById('blist').innerHTML=BK.map((k,i)=>`
  <div class="brow">
    <div class="bdot" style="background:${BC[i]};"></div>
    <div class="blabel">${BL[i]}</div>
    <div class="bamount">${fmt(b[k])}<span class="bpct"> · ${Math.round((b[k]/total)*100)}%</span></div>
  </div>`).join('');

