input.newString:
function shareResult(){
  const ranked=rankDests();
  const d=DESTS.find(x=>x.id===ranked[0].id);
  const pct=Math.min(100,ranked[0].match);
  const txt=`🌍 My travel ideal type is ${d.name} ${d.emoji} (${pct}% match)! Find yours at Travel Ideal Type World Cup ✈️`;
  const url=location.href;
  if(navigator.share){
    navigator.share({title:'Travel Ideal Type World Cup',text:txt,url:url})
      .catch(err=>{
        if(err && err.name==='AbortError') return;   // user dismissed the sheet
        copyText(`${txt}\n${url}`);
      });
  }else if(navigator.clipboard){
    navigator.clipboard.writeText(`${txt}\n${url}`)
      .then(()=>toast('Result copied to clipboard! 📋'))
      .catch(()=>copyText(`${txt}\n${url}`));
  }else{
    copyText(`${txt}\n${url}`);
  }
}

/* Clipboard fallback: execCommand works even when the async Clipboard API is
   blocked (insecure context, denied permission, unfocused document). */
function copyText(txt){
  try{
    const ta=document.createElement('textarea');
    ta.value=txt;
    ta.setAttribute('readonly','');
    ta.style.cssText='position:fixed;top:0;left:-9999px;opacity:0';
    document.body.appendChild(ta);
    ta.select();
    ta.setSelectionRange(0,txt.length);
    const ok=document.execCommand('copy');
    document.body.removeChild(ta);
    toast(ok?'Result copied to clipboard! 📋':'Copy failed — please copy manually.');
  }catch(e){
    toast('Copy failed — please copy manually.');
  }
}

function toast(msg){
  const el=document.createElement('div');
  el.textContent=msg;
  el.style.cssText='position:fixed;left:50%;bottom:28px;transform:translateX(-50%);z-index:10000;'+
    'background:rgba(20,22,48,.95);color:#E8EAFF;border:1px solid rgba(255,255,255,.14);'+
