function axisLeanText(ax,raw){
  const pair=axisLabels(ax);
  const word=raw<-0.5?pair[0]:(raw>0.5?pair[1]:(LANG==='ko'?'중립':'Balanced'));
  // \w is ASCII-only in JS, so it would strip every Hangul syllable.
  // Use Unicode property escapes to keep letters in any script.
  return word.replace(/[^\p{L}\p{N}\s]/gu,'').trim();
}

