    for (const p of ['a','b','a','b','a','b','a','b','a','b']) { window.pickChoice(p); await sleep(650); }
    await sleep(3400);
    out.noChart = {
      itin: document.getElementById('itin-list').children.length,
      tips: document.getElementById('tips-grid').children.length,
      pack: document.getElementById('pack-grid').children.length,
      chartHidden: getComputedStyle(document.getElementById('budget-chart-wrap')).display,
      blistRows: document.getElementById('blist').children.length,
      pctShown: document.getElementById('blist').textContent.includes('%')
    };
    window.Chart = realChart;

    // 2. share fallback (clipboard blocked)
    navigator.clipboard.writeText = () => Promise.reject(new Error('blocked'));
    window.shareResult(); await sleep(300);
    out.toastShown = !!document.querySelector('body > div[style*="border-radius: 999px"]') ||
                     /copy/i.test(document.body.innerText);
    out.toastText = [...document.querySelectorAll('body > div')].map(d=>d.textContent).filter(t=>t&&t.length<80).pop();
    return out;
  })();
})()
